using UnityEngine;
using System;
[DefaultExecutionOrder(180)]
public class WoodlandHostile:MonoBehaviour {
 public WoodlandPlayer player;public WoodlandAnatomy anatomy;public Animator animator;public Transform rifle,muzzle,rightGrip,leftGrip;public Light flash;public AudioSource audioSource;public AudioClip shot;
 public bool retreatWhenWounded;float withdrawalUntil;
 public bool indoor;public float floorHeight=.04f;
 float Floor(Vector3 p)=>indoor?floorHeight:WoodlandCompanion.Ground(p.x,p.z)+.04f;
 public string State{get;private set;}="Patrol";public int ShotsFired{get;private set;}public int magazine=30;
 Vector3 home,lastKnown,destination;float awareness,lastSeen=-100,nextThink,nextShot,reloadUntil,hurtUntil,flashUntil,moveSpeed,patrolTime;int burst;bool deadHandled,hasMemory;Transform spine,rightUpper,rightElbow,rightHand,leftUpper,leftElbow,leftHand;Quaternion[] pose=new Quaternion[5];bool posed;
 Transform Bone(string name){foreach(var t in GetComponentsInChildren<Transform>())if(t.name.EndsWith(":"+name))return t;return null;}
 void Start(){home=transform.position;destination=home;spine=Bone("Spine2");rightUpper=Bone("RightArm");rightElbow=Bone("RightForeArm");rightHand=Bone("RightHand");leftUpper=Bone("LeftArm");leftElbow=Bone("LeftForeArm");leftHand=Bone("LeftHand");anatomy.HitOccurred+=Wounded;player.Gunshot+=Hear;}
 void OnDestroy(){if(anatomy)anatomy.HitOccurred-=Wounded;if(player)player.Gunshot-=Hear;}
 void Hear(Vector3 point){if(anatomy.Incapacitated||Vector3.Distance(point,transform.position)>45)return;lastKnown=point;hasMemory=true;awareness=1;lastSeen=Time.time;destination=point;State="Investigate gunfire";}
 void Wounded(BodyRegion r,float damage,Vector3 point,Vector3 dir){hurtUntil=Time.time+1.1f;nextShot=Mathf.Max(nextShot,hurtUntil+.3f);burst=0;lastKnown=transform.position-dir.normalized*8;hasMemory=true;awareness=1;lastSeen=Time.time;destination=FindCover(lastKnown);State="Taking cover";if(retreatWhenWounded&&damage>=18){withdrawalUntil=Time.time+90;Vector3 away=(transform.position-player.transform.position);away.y=0;destination=transform.position+away.normalized*3;destination.x=Mathf.Clamp(destination.x,197.2f,202.8f);destination.z=Mathf.Clamp(destination.z,21,27);State="Wounded retreat";}}
 bool FirstHit(Vector3 origin,Vector3 direction,float distance,out RaycastHit first){var hits=Physics.RaycastAll(origin,direction,distance,~0,QueryTriggerInteraction.Collide);Array.Sort(hits,(a,b)=>a.distance.CompareTo(b.distance));foreach(var h in hits){if(h.collider.transform.IsChildOf(transform))continue;if(h.collider.isTrigger&&!h.collider.GetComponentInParent<WoodlandHitZone>())continue;first=h;return true;}first=default;return false;}
 public bool CanSeePlayer(){if(!player||player.anatomy.Incapacitated)return false;Vector3 eye=transform.position+Vector3.up*1.5f,target=player.transform.position+Vector3.up*1.15f;Vector3 delta=target-eye;if(delta.magnitude>25||(!hasMemory&&Vector3.Angle(transform.forward,delta)>65))return false;return !FirstHit(eye,delta.normalized,delta.magnitude,out var hit)||hit.collider.transform.IsChildOf(player.transform);}
 Vector3 FindCover(Vector3 threat){Vector3 best=transform.position;float score=0;foreach(var c in Physics.OverlapSphere(transform.position,7,~0,QueryTriggerInteraction.Ignore)){if(c.transform.IsChildOf(transform)||c.transform.IsChildOf(player.transform)||c.bounds.size.y<.8f||c.bounds.size.x>8)continue;Vector3 away=c.bounds.center-threat;away.y=0;if(away.sqrMagnitude<.01f)continue;Vector3 q=c.bounds.center+away.normalized*(Mathf.Max(c.bounds.extents.x,c.bounds.extents.z)+.65f);q.y=Floor(q);Vector3 to=threat+Vector3.up-q-Vector3.up;if(Physics.Raycast(q+Vector3.up,to.normalized,out var hit,to.magnitude,~0,QueryTriggerInteraction.Ignore)&&!hit.collider.transform.IsChildOf(player.transform)){float s=10-Vector3.Distance(transform.position,q);if(s>score){best=q;score=s;}}}return best;}
 void RestorePose(){if(!posed)return;if(!anatomy.Incapacitated){Transform[] ts={spine,rightUpper,rightElbow,leftUpper,leftElbow};for(int i=0;i<ts.Length;i++)if(ts[i])ts[i].localRotation=pose[i];}posed=false;}
 void Update(){RestorePose();if(flash)flash.enabled=Time.time<flashUntil;if(anatomy.Incapacitated){if(!deadHandled){deadHandled=true;DropRifle();State="Incapacitated";}if(flash)flash.enabled=false;return;}if(player.anatomy.Incapacitated){State="Hold";animator.SetFloat("Speed",0);return;}
 var reaction=GetComponent<WoodlandNPCInjury>();if(reaction&&reaction.HoldsPosition){State=reaction.CurrentReaction.ToString();animator.SetFloat("Speed",0);return;}
 if(Time.time<withdrawalUntil){State="Wounded retreat";Move(Time.deltaTime,false);return;}
 bool visible=CanSeePlayer();if(visible){awareness=Mathf.Min(1,awareness+Time.deltaTime/.9f);lastKnown=player.transform.position;hasMemory=true;lastSeen=Time.time;}else awareness=Mathf.Max(0,awareness-Time.deltaTime*.06f);
 if(Time.time>=nextThink){nextThink=Time.time+.35f;if(Time.time<hurtUntil){}else if(visible&&awareness>=1){State=reloadUntil>Time.time?"Reloading":"Engage";float dist=Vector3.Distance(transform.position,lastKnown);if(dist<6)destination=transform.position+(transform.position-lastKnown).normalized*3;else if(Time.time>patrolTime){patrolTime=Time.time+3;Vector3 cover=FindCover(lastKnown);destination=Vector3.Distance(cover,transform.position)>.5f?cover:transform.position+transform.right*UnityEngine.Random.Range(-2f,2f);}}else if(hasMemory&&Time.time-lastSeen<12){State="Search last position";destination=lastKnown;}else{hasMemory=false;State="Patrol";if(Vector3.Distance(transform.position,destination)<.7f){float z=home.z+Mathf.Sin(Time.time*.15f)*4;destination=indoor?new Vector3(home.x,floorHeight,home.z+Mathf.Sin(Time.time*.15f)*1.2f):new Vector3(WoodlandCompanion.PathX(z),WoodlandCompanion.Ground(WoodlandCompanion.PathX(z),z)+.04f,z);}}}
 Move(Time.deltaTime,visible);if(!(reaction&&reaction.BlocksWeaponUse)&&visible&&awareness>=1&&Time.time>=hurtUntil&&Time.time>=nextShot&&Time.time>=reloadUntil)Shoot();}
 void Move(float dt,bool visible){Vector3 before=transform.position;Vector3 d=destination-transform.position;d.y=0;float desired=d.magnitude>.55f?(State=="Taking cover"?2.5f:hasMemory?1.4f:.85f):0;float sideways=Mathf.Abs(Vector3.Dot(d.normalized,transform.right));if(visible)desired*=Mathf.Lerp(1,.6f,sideways);desired*=anatomy.MovementMultiplier;moveSpeed=Mathf.MoveTowards(moveSpeed,desired,dt*4);if(moveSpeed>.02f){Vector3 dir=d.normalized;bool found=false;for(int i=0;i<7;i++){float angle=i==0?0:((i+1)/2)*30*(i%2==0?-1:1);Vector3 test=Quaternion.Euler(0,angle,0)*dir;bool blocked=false;foreach(var h in Physics.SphereCastAll(transform.position+Vector3.up*.7f,.23f,test,.6f,~0,QueryTriggerInteraction.Ignore))if(!h.collider.transform.IsChildOf(transform))blocked=true;if(!blocked){dir=test;found=true;break;}}if(found){transform.position+=dir*Mathf.Min(d.magnitude,moveSpeed*dt);var p=transform.position;p.y=Floor(p);transform.position=p;}else moveSpeed=0;}
 Vector3 facing=(visible?lastKnown:destination)-transform.position;facing.y=0;if(facing.sqrMagnitude>.03f)transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(facing),1-Mathf.Exp(-dt*5));float actual=Vector3.Distance(before,transform.position)/Mathf.Max(dt,.001f);animator.SetFloat("Speed",actual);animator.speed=actual>.1f?Mathf.Clamp(actual/1.35f,.55f,1.3f):1;}
 void Shoot(){if(magazine<=0){reloadUntil=Time.time+3.2f;nextShot=reloadUntil+.4f;magazine=30;burst=0;State="Reloading";return;}Vector3 target=player.transform.position+Vector3.up*1.05f;Vector3 direction=(target-muzzle.position).normalized;float spread=2.2f+moveSpeed*1.4f+anatomy.AimInstability*2;direction=Quaternion.Euler(UnityEngine.Random.Range(-spread,spread),UnityEngine.Random.Range(-spread,spread),0)*direction;
 // The muzzle ray respects cover and intervening people; no direct guaranteed damage.
 bool struck=FirstHit(muzzle.position,direction,35,out var hit);player.IncomingRound(muzzle.position,struck?hit.point:muzzle.position+direction*35);if(struck){if(hit.collider.transform.IsChildOf(player.transform)){var z=hit.collider.GetComponentInParent<WoodlandHitZone>();if(z)z.Receive(19,hit.point,direction);else player.anatomy.Hit(BodyRegion.Chest,19,InjuryKind.Projectile,hit.point,direction,.25f);}else{var z=hit.collider.GetComponentInParent<WoodlandHitZone>();if(z)z.Receive(19,hit.point,direction);}}
 magazine--;ShotsFired++;flashUntil=Time.time+.05f;WoodlandGunshotAcoustics.Play(player,muzzle.position,shot,false,indoor,transform);burst++;nextShot=Time.time+(burst>=3?UnityEngine.Random.Range(1.2f,2.1f):.22f);if(burst>=3)burst=0;}
 void LateUpdate(){if(anatomy.Incapacitated||!spine||!rifle)return;Vector3 target=hasMemory?lastKnown+Vector3.up*1.1f:transform.position+transform.forward*10+Vector3.up;rifle.position=spine.position+transform.right*.12f+transform.forward*.16f+Vector3.up*.035f;rifle.rotation=Quaternion.LookRotation(target-rifle.position,Vector3.up);if(Time.time<withdrawalUntil){rifle.rotation*=Quaternion.Euler(38,0,-12);SeatRifleInHand();return;}if(Time.time<reloadUntil)rifle.rotation*=Quaternion.Euler(28,0,-18);var injury=GetComponent<WoodlandNPCInjury>();if(Time.time<hurtUntil||(injury&&injury.BlocksWeaponUse)){SeatRifleInHand();return;}Transform[] ts={spine,rightUpper,rightElbow,leftUpper,leftElbow};for(int i=0;i<ts.Length;i++)if(ts[i])pose[i]=ts[i].localRotation;posed=true;AimArm(rightUpper,rightElbow,rightHand,rightGrip.position);SeatRifleInHand();AimArm(leftUpper,leftElbow,leftHand,leftGrip.position);}
 // Translate using world-space grip coordinates: valid for scaled and nested weapon meshes.
 void SeatRifleInHand(){if(rifle&&rightHand&&rightGrip)rifle.position+=rightHand.position-rightGrip.position;}
 void DropRifle(){
 if(!rifle)return;SeatRifleInHand();if(flash)flash.enabled=false;
 var ownerColliders=GetComponentsInChildren<Collider>();
 rifle.SetParent(transform.parent,true);
 // Use a simple local box for dropped-weapon physics, independent of the animated skeleton.
 var bounds=new Bounds(Vector3.zero,Vector3.zero);bool first=true;
 foreach(var renderer in rifle.GetComponentsInChildren<Renderer>()){
 var b=renderer.bounds;for(int i=0;i<8;i++){var corner=b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1));var local=rifle.InverseTransformPoint(corner);if(first){bounds=new Bounds(local,Vector3.zero);first=false;}else bounds.Encapsulate(local);}}
 foreach(var c in rifle.GetComponentsInChildren<Collider>())c.enabled=false;
 var box=rifle.gameObject.AddComponent<BoxCollider>();box.center=bounds.center;box.size=first?new Vector3(.12f,.22f,.8f):bounds.size;
 foreach(var c in ownerColliders)if(c&&c!=box)Physics.IgnoreCollision(box,c);
 var body=rifle.GetComponent<Rigidbody>();if(!body)body=rifle.gameObject.AddComponent<Rigidbody>();body.isKinematic=false;body.useGravity=true;body.mass=3.2f;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.interpolation=RigidbodyInterpolation.Interpolate;
 }
 void AimArm(Transform upper,Transform elbow,Transform hand,Vector3 target){if(!upper||!elbow||!hand)return;Vector3 root=upper.position;float a=Vector3.Distance(root,elbow.position),b=Vector3.Distance(elbow.position,hand.position);Vector3 axis=(target-root).normalized;float d=Mathf.Clamp(Vector3.Distance(root,target),.03f,a+b-.003f);float along=(a*a+d*d-b*b)/(2*d);float side=Vector3.Dot(root-transform.position,transform.right)>0?1:-1;Vector3 bend=Vector3.ProjectOnPlane(-transform.up*.8f+transform.right*side*.45f,axis).normalized;Vector3 joint=root+axis*along+bend*Mathf.Sqrt(Mathf.Max(0,a*a-along*along));upper.rotation=Quaternion.FromToRotation(elbow.position-root,joint-root)*upper.rotation;elbow.rotation=Quaternion.FromToRotation(hand.position-elbow.position,target-elbow.position)*elbow.rotation;}
}
